const b = $input.first().json.body || {};
const token = String(b.token || '');
if (!/^[a-f0-9]{64}$/.test(token)) return [{ json: { ok: false, error: 'session_invalide' } }];
const q0 = "SELECT me.id AS me_id, o.id, o.gender, o.display_name, o.avatar_color, (YEAR(CURDATE()) - op.birth_year) AS age, op.region, op.city, op.belief, op.religious_level, op.marital_status, op.wants_children, op.marriage_timeframe, REPLACE(REPLACE(TO_BASE64(ph.data), CHAR(10), ''), CHAR(13), '') AS photo " +
"FROM (SELECT 1 AS x) d " +
"LEFT JOIN members me ON me.session_hash=SHA2('" + token + "',256) AND me.session_expires > NOW() AND me.status='actif' " +
"LEFT JOIN profiles mp ON mp.member_id=me.id " +
"LEFT JOIN search_preferences ms ON ms.member_id=me.id " +
"LEFT JOIN (members o JOIN profiles op ON op.member_id=o.id JOIN search_preferences os ON os.member_id=o.id) " +
"ON me.id IS NOT NULL AND o.id <> me.id AND o.gender <> me.gender AND o.status='actif' AND o.identity_verified=1 " +
"AND (YEAR(CURDATE()) - op.birth_year) BETWEEN ms.age_min AND ms.age_max " +
"AND (YEAR(CURDATE()) - mp.birth_year) BETWEEN os.age_min AND os.age_max " +
"LEFT JOIN member_photos ph ON ph.member_id=o.id " +
"ORDER BY o.created_at DESC LIMIT 30";
return [{ json: { ok: true, q0 } }];

const rows = $input.all().map(i => i.json);
if (!rows.length || rows[0].me_id === null || rows[0].me_id === undefined) return [{ json: { success: false, error: 'session_invalide' } }];
const profils = rows.filter(r => r.id !== null && r.id !== undefined).map(r => ({
  id: r.id, nom: r.display_name, couleur: r.avatar_color, genre: r.gender, age: Number(r.age), region: r.region, ville: r.city,
  croyance: r.belief, pratique: r.religious_level, situation: r.marital_status,
  enfants: r.wants_children, delai: r.marriage_timeframe,
  photo: r.photo ? 'data:image/jpeg;base64,' + r.photo : null
}));
return [{ json: { success: true, profils } }];
